echo "=== Fetch module registry from production ==="
curl -s "https://ivx-holdings-platform.onrender.com/api/ivx/module-registry" 2>/dev/null | python3 -c "
import json, sys
try:
    d = json.load(sys.stdin)
    print('Keys:', list(d.keys()) if isinstance(d, dict) else f'list of {len(d)}')
    if isinstance(d, dict):
        for k, v in d.items():
            if isinstance(v, list):
                print(f'{k}: {len(v)} items')
            elif isinstance(v, dict):
                print(f'{k}: {list(v.keys())[:10]}')
            else:
                print(f'{k}: {v}')
except Exception as e:
    print(f'Error: {e}')
    sys.stdin.seek(0)
    print(sys.stdin.read()[:500])
" 2>/dev/null

